{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Ultimate Bad Beat",
          "intent": "Establish Artie's mundane life and his absurdly unlucky death by vending machine.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie dies and the 'Death-Trap Tutorial' loading screen appears."
        },
        {
          "section_id": 2,
          "title": "Welcome to the Grinder",
          "intent": "Artie navigates the initial tutorial traps and discovers his broken Luck stat.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "Artie unlocks the 'Crit-and-Quit' passive skill."
        },
        {
          "section_id": 3,
          "title": "Bypassing the Gatekeeper",
          "intent": "Artie uses his glitchy luck to skip the tutorial boss entirely.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie steps through the tutorial exit portal into the main world."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Oakhaven Arrival",
          "intent": "Artie enters the starter town and realizes he has no gear but infinite potential for chaos.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie reaches the town square and finds the local Potion Shop."
        },
        {
          "section_id": 2,
          "title": "The Potion Arbitrage",
          "intent": "Artie exploits a shop-buyback bug caused by his Luck stat to generate infinite gold.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "The local economy crashes and a bounty is placed on Artie's head."
        },
        {
          "section_id": 3,
          "title": "Cornered by the Law",
          "intent": "Artie flees the town guards and is intercepted by a group of high-level Paladins.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie agrees to join the Paladins' quest to avoid immediate arrest."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "The Glass Cannon Audition",
          "intent": "Artie bluffs his way into the party by pretending to be a high-level mage.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The party departs for the Forbidden Zone."
        },
        {
          "section_id": 2,
          "title": "Tactical Incompetence",
          "intent": "Artie survives early skirmishes by exploiting line-of-sight bugs and friendly fire mechanics.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "The party reaches the entrance of the glitched dungeon."
        },
        {
          "section_id": 3,
          "title": "Into the Deep End",
          "intent": "The party enters the dungeon and discovers the environment is actively corrupting.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "A massive trap isolates Artie from the rest of the party."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "Solo Queue Nightmares",
          "intent": "Artie must navigate the inner sanctum alone while the Paladins are CC'd.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie enters the boss chamber of the Glitched Sentinel."
        },
        {
          "section_id": 2,
          "title": "The Chain of Luck",
          "intent": "Artie engages the boss, relying on a continuous string of 0.01% critical hits to stay alive.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The Boss is defeated by a final, reality-warping critical strike."
        },
        {
          "section_id": 3,
          "title": "The Forbidden Loot",
          "intent": "Artie loots the boss and discovers the Glitch-Shard, which talks back.",
          "section_role": "falling_action",
          "target_scene_count": 3,
          "end_condition": "Artie reunites with his party, hiding the shard as they exit the dungeon."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "Signal in the Noise",
          "intent": "Artie uses the Shard to track down the source of the world's instability.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie arrives at the 'Ghost Tavern' on the edge of the world map."
        },
        {
          "section_id": 2,
          "title": "The Admin's Lament",
          "intent": "Artie meets the Admin Ghost and learns the System is scheduled for a full wipe.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "The Admin Ghost reveals the location of the Source Core."
        },
        {
          "section_id": 3,
          "title": "The Bug Becomes a Feature",
          "intent": "Artie decides to steal the Core to prevent the wipe, accepting his role as a 'Global Error'.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie begins the journey to the Capital's High Vault."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "Breaking the Capital",
          "intent": "Artie infiltrates the most secure city in the game using 'unintended travel mechanics'.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie reaches the doors of the Source Vault."
        },
        {
          "section_id": 2,
          "title": "The Grand Larceny",
          "intent": "Artie bypasses the Vault's logic puzzles by literally breaking the physics engine.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "Artie physically removes the Source Core from its pedestal."
        },
        {
          "section_id": 3,
          "title": "Emergency Maintenance",
          "intent": "The System detects the theft and begins a world-wide shutdown sequence.",
          "section_role": "falling_action",
          "target_scene_count": 3,
          "end_condition": "Artie escapes the Capital as the sky starts to pixelate and dissolve."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Deletion Wave",
          "intent": "Artie fights off 'System Cleaners' while searching for a stable zone.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Artie finds a group of other glitched NPCs and players hiding in a void-pocket."
        },
        {
          "section_id": 2,
          "title": "Building the Firewall",
          "intent": "Artie uses the Source Core to stabilize a permanent 'Safe Zone' for the glitched.",
          "section_role": "rising_action",
          "target_scene_count": 3,
          "end_condition": "The Safe Zone is successfully shielded from the System's purge."
        },
        {
          "section_id": 3,
          "title": "Patch 2.0 Can Wait",
          "intent": "Artie establishes himself as the leader of the digital resistance.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie sits on his new 'throne' and prepares for the first counter-attack against the System."
        }
      ]
    }
  ]
}

